import { readFile, writeFile, mkdir, cp } from 'node:fs/promises';
import { build } from 'esbuild';
await mkdir('src', { recursive: true });
const result = await build({
  entryPoints: ['web/client.ts'],
  bundle: true,
  write: false,
  target: 'es2022',
  minify: true,
  platform: 'browser',
});
const html = await readFile('web/index.html', 'utf8');
const css = await readFile('web/style.css', 'utf8');
await writeFile(
  'src/assets.generated.ts',
  '// Generated by scripts/build.mjs\nexport const html=' +
    JSON.stringify(html) +
    ';\nexport const css=' +
    JSON.stringify(css) +
    ';\nexport const client=' +
    JSON.stringify(result.outputFiles[0].text) +
    ';\n',
);
await mkdir('dist/server', { recursive: true });
await build({
  entryPoints: ['src/worker.ts'],
  bundle: true,
  outfile: 'dist/server/index.js',
  format: 'esm',
  platform: 'browser',
  target: 'es2022',
  minify: true,
});
// A public clone can build without the private deployment's Site identity.
// Only an explicitly configured Sites checkout needs the hosting manifest.
try {
  const manifest = await readFile('.openai/hosting.json', 'utf8');
  await mkdir('dist/.openai', { recursive: true });
  await writeFile('dist/.openai/hosting.json', manifest);
} catch (error) {
  if (error.code !== 'ENOENT') throw error;
}
await cp('drizzle', 'dist/drizzle', { recursive: true });
console.log('Built application and browser assets.');
